from pathlib import Path
import sys
p=Path(sys.argv[1])/'src/model'
h=(p/'world.h').read_text().replace('    std::uint32_t camps_version = 0;', '    std::uint32_t camp_geometry_version = 0; // only camp tiles becoming occupied or empty\n    std::uint32_t camps_version = 0;');(p/'world.h').write_text(h)
s=(p/'world.cc').read_text();s=s.replace('    const bool moved = c.state != CampState::respawning;','    camp_geometry_version += c.state == CampState::alive;\n    const bool moved = c.state != CampState::respawning;');s=s.replace('            c.state = CampState::alive;\n            restore', '            ++camp_geometry_version;\n            c.state = CampState::alive;\n            restore');s=s.replace('    c.version += c.state != previous;','    camp_geometry_version += (c.state == CampState::alive) != (previous == CampState::alive);\n    c.version += c.state != previous;');s=s.replace('                version += hp != health[i];','                if constexpr (live) camp_geometry_version += (hp > 0) != (health[i] > 0);\n                version += hp != health[i];');(p/'world.cc').write_text(s)
s=(p/'pathing.cc').read_text();s=s.replace('live_camps_version_ != world_.camps_version','live_camps_version_ != world_.camp_geometry_version').replace('live_camps_version_ = world_.camps_version','live_camps_version_ = world_.camp_geometry_version');(p/'pathing.cc').write_text(s)
s=(p/'safety.cc').read_text().replace('sets_camps_version_ == world.camps_version','sets_camps_version_ == world.camp_geometry_version').replace('sets_camps_version_ = world.camps_version','sets_camps_version_ = world.camp_geometry_version');(p/'safety.cc').write_text(s)
